<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#17221f}h1,h2{color:#155c4a}.cover{page-break-after:always;padding-top:120px}.finding{page-break-inside:avoid;margin:18px 0}.footer{position:fixed;bottom:-20px;font-size:9px}</style></head><body><div class="footer">Acorn Safety Services | Health &amp; Safety Healthcheck</div><section class="cover"><h1>Health &amp; Safety Healthcheck Report</h1><p>Covering Health &amp; Safety · Fire · Legionella · Asbestos</p><h2><?php echo esc_html($report['meta']['company']);?></h2><p>Self-assessment report · <?php echo esc_html($report['meta']['assessment_date']);?></p></section><h1>Executive summary</h1><p><?php echo (int)$report['summary']['priority_count'];?> priority actions · <?php echo (int)$report['summary']['review_count'];?> areas to review · <?php echo (int)$report['summary']['addressed_count'];?> addressed</p><?php foreach(['addressed','review','priority']as$type):?><h2><?php echo esc_html($report['sections'][$type]['label']);?></h2><?php foreach($report[$type]as$item):?><div class="finding"><h3><?php echo esc_html($item['question_text']);?></h3><p><?php echo esc_html($item['positive_text']??'Review recommended.');?></p></div><?php endforeach;?><?php endforeach;?><p><?php echo esc_html($report['disclaimer']);?></p></body></html>
